import React from 'react';
import { Scene3D } from './Scene3D';
import { View3DSettingsDialog } from './View3DSettingsDialog';
import {
  DEFAULT_VIEW3D_SETTINGS,
    type View3DSettings,
    } from './view3dTypes';
import type { Wall, Window as WindowType, Door, Column, Stair, StairElement } from '../../core/types';
      interface Props {
          walls: Wall[];
            windows: WindowType[];
              doors: Door[];
                columns: Column[];
                  stairs: Stair[];
                    stairElements: StairElement[];
                      floorHeights: number[];
                        onClose: () => void;
                        }
      

              const STORAGE_KEY = 'view3d_settings_v1';

              function loadSettings(): View3DSettings {
                try {
                    const saved = localStorage.getItem(STORAGE_KEY);
                        if (saved) {
                              const parsed = JSON.parse(saved);
                                    return { ...DEFAULT_VIEW3D_SETTINGS, ...parsed };
                                        }
                                          } catch (e) {
                                              // ignore
                                                }
                                                  return { ...DEFAULT_VIEW3D_SETTINGS };
                                                  }

export const View3DPanel: React.FC<Props> = ({
    walls, windows, doors, columns, stairs, stairElements, floorHeights, onClose,
    }) => {
                                                  const [settings, setSettings] = React.useState<View3DSettings>(loadSettings);
                                                      const [showSettings, setShowSettings] = React.useState(false);

                                                        // ✅ حفظ تلقائي عند كل تغيير
                                                          React.useEffect(() => {
                                                              try {
                                                                    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
                                                                        } catch (e) {
                                                                              // ignore
                                                                                  }
                                                                                    }, [settings]);

                                                                                      return (
                                                                                          <div
                                                                                                style={{
                                                                                                        position: 'fixed',
                                                                                                                inset: 0,
                                                                                                                        zIndex: 9999,
                                                                                                                                background: '#000',
                                                                                                                                        display: 'flex',
                                                                                                                                                flexDirection: 'column',
                                                                                                                                                      }}
                                                                                                                                                          >
                                                                                                                                                                {/* شريط علوي */}
                                                                                                                                                                      <div
                                                                                                                                                                              style={{
                                                                                                                                                                                        position: 'absolute',
                                                                                                                                                                                                  top: 0,
                                                                                                                                                                                                            left: 0,
                                                                                                                                                                                                                      right: 0,
                                                                                                                                                                                                                                height: 50,
                                                                                                                                                                                                                                          background: 'rgba(0,0,0,0.7)',
                                                                                                                                                                                                                                                    display: 'flex',
                                                                                                                                                                                                                                                              alignItems: 'center',
                                                                                                                                                                                                                                                                        justifyContent: 'space-between',
                                                                                                                                                                                                                                                                                  padding: '0 12px',
                                                                                                                                                                                                                                                                                            zIndex: 10,
                                                                                                                                                                                                                                                                                                    }}
                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                  <div style={{ color: '#fff', fontWeight: 700, fontSize: 16 }}>
                                                                                                                                                                                                                                                                                                                            🏠 المنظور ثلاثي الأبعاد
                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                            <div style={{ display: 'flex', gap: 8 }}>
                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                  onClick={() => setShowSettings(true)}
                                                                                                                                                                                                                                                                                                                                                                              title="إعدادات المنظور"
                                                                                                                                                                                                                                                                                                                                                                                          style={{
                                                                                                                                                                                                                                                                                                                                                                                                        background: '#f80',
                                                                                                                                                                                                                                                                                                                                                                                                                      color: '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                    border: 'none',
                                                                                                                                                                                                                                                                                                                                                                                                                                                  borderRadius: 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: '8px 12px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              fontWeight: 700,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fontSize: 16,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          cursor: 'pointer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ⚙️
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onClick={onClose}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      background: '#dc3545',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  border: 'none',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                borderRadius: 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              padding: '8px 16px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fontWeight: 700,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fontSize: 14,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cursor: 'pointer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ✖ إغلاق
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {/* المشهد */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div style={{ flex: 1, position: 'relative' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {walls.length === 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          display: 'flex',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alignItems: 'center',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      justifyContent: 'center',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    height: '100%',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  color: '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fontSize: 18,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              textAlign: 'center',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: 20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              لا توجد جدران لعرضها.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <br />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ارسم مخططاً أولاً ثم افتح المنظور.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Scene3D
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              walls={walls}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          windows={windows}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      doors={doors}
                                                                                                              columns={columns}
                                                                                                                stairs={stairs}
                                                                                                                  stairElements={stairElements}
                                                                                                                    floorHeights={floorHeights}                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    settings={settings}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {/* نافذة الإعدادات */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {showSettings && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View3DSettingsDialog
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        settings={settings}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onChange={setSettings}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onClose={() => setShowSettings(false)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };